,{\"control_ids\":[\"xml.transition\"],\"evidence\":[{\"quote\":\"licensed firms that intend to submit STRs via the XML format are required to follow the XML schema provided separately by the JFIU and liaise with it as soon as possible to arrange a technical test to ensure a smooth transition.\",\"unit_id\":\"da12aecad4e68.u14.2439\"}],\"item_id\":\"reading_4\",\"reason\":\"Addresses XML schema and technical-test dependencies, which are separately controlled from filing method.\",\"status\":\"ASSIGNED\"},{\"control_ids\":[\"submission.compliance\"],\"evidence\":[{\"quote\":\"Hongkong Post e-Cert (electronic certificate) is required for this submission.\",\"unit_id\":\"da12aecad4e68.u30.3569\"}],\"item_id\":\"streams2.channel_method_certificate\",\"reason\":\"Provides the most complete channel, method and submission-specific certificate formulation while leaving certificate mechanics for evidence.\",\"status\":\"ASSIGNED\"},{\"control_ids\":[\"submission.compliance\"],\"evidence\":[{\"quote\":\"Hongkong Post e-Cert (electronic certificate) is required for this submission.\",\"unit_id\":\"da12aecad4e68.u30.3569\"}],\"item_id\":\"channel_control_with_attached_qualifications\",\"reason\":\"Retains channel, method, XML-schema and e-Cert qualifications and keeps later resubmission separate.\",\"status\":\"ASSIGNED\"},{\"control_ids\":[\"resubmission.history\"],\"evidence\":[{\"quote\":\"For STRs submitted to the JFIU via channels other than STREAMS 2 following its implementation, licensed firms are required to re-submit the STRs via STREAMS 2.\",\"unit_id\":\"da12aecad4e68.u28.3334\"}],\"item_id\":\"streams2.resubmission_trigger\",\"reason\":\"Uses report history to identify whether any qualifying post-launch other-channel submission occurred.\",\"status\":\"ASSIGNED\"},{\"control_ids\":[\"urgent.contact\"],\"evidence\":[{\"quote\":\"for any STRs requiring urgent submission during the blackout period of STREAMS, please contact the JFIU directly by email (jfiu@police.gov.h